INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('b13c5e62-8289-4bc0-b94a-6ed867c1e5fa', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'elliptical', '(문체가) 생략적이고 압축적인', '{compressed,cryptic}', '{explicit,elaborate}', 'The poem''s elliptical syntax forces readers to fill in the missing connections themselves.', 'His elliptical prose style leaves much unsaid, relying on suggestion rather than statement.', 63, '2026-09-16 06:44:32.67489+00', 4, '문체 및 통사 구조 분석 지문에서 등장하는 수사학적 어휘') ON CONFLICT (book_id, word) DO NOTHING;
