INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('a9f9daa0-e9f2-4553-a009-eafe835f5041', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'gravitas', '위엄, 무게감 있는 진지함', '{solemnity,dignity}', '{levity,frivolity}', 'The elder statesman''s speech carried a gravitas that younger orators struggled to emulate.', 'The tragedy''s protagonist speaks with a gravitas befitting his tragic downfall.', 94, '2026-09-16 06:44:32.67489+00', 4, '수사학적 어조 분석에서 화자의 무게감을 설명할 때 사용') ON CONFLICT (book_id, word) DO NOTHING;
