INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('5331e9ae-f752-48ee-b6b8-18deccdd2f9f', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'insinuate', '암시하다, 넌지시 말하다', '{imply,hint}', '{declare,assert}', 'The narrator insinuates that the merchant''s wealth was gained through deceit.', 'Without stating it directly, the essay insinuates a critique of colonial policy.', 96, '2026-09-16 06:44:32.67489+00', 3, '함축적 표현이나 화자의 태도를 묻는 문항에서 자주 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('19373d57-815d-42fc-9326-bcdc971d343d', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'empathetic', '공감하는, 감정 이입하는', '{compassionate,sympathetic}', '{indifferent,callous}', 'The author''s empathetic narration invites readers to see the world through the orphan''s eyes.', 'Critics noted the empathetic tone with which the biographer treated her subject''s failures.', 97, '2026-09-16 06:44:32.67489+00', 3, '서술자의 태도와 어조를 분석하는 지문에서 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('1df99cd9-fb97-4ac8-9d84-d843d38f3f68', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'assonance', '모음운, 유사 모음의 반복', '{"vowel rhyme","vowel repetition"}', '{dissonance,discord}', 'The poem''s assonance creates a soft, musical quality that mirrors its pastoral setting.', 'Students were asked to identify the assonance linking the second and fourth lines.', 98, '2026-09-16 06:44:32.67489+00', 4, '시 분석 지문에서 음운적 장치를 식별하는 문항에 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('f219f904-5533-4470-8cf6-50192e06e740', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'meter', '운율, 시의 리듬 구조', '{rhythm,cadence}', '{arrhythmia,irregularity}', 'The sonnet''s strict meter contrasts with the free verse of later poems in the collection.', 'Analyzing the meter reveals how the poet manipulates rhythm to convey urgency.', 99, '2026-09-16 06:44:32.67489+00', 3, '시 형식 분석에서 필수적으로 다루어지는 개념어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('5beab35a-9e64-4746-a86a-4c02be5b592f', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'stanza', '연, 시의 단락 구분', '{verse,strophe}', '{prose,paragraph}', 'Each stanza of the elegy mourns a different aspect of the poet''s loss.', 'The final stanza shifts abruptly from despair to quiet acceptance.', 100, '2026-09-16 06:44:32.67489+00', 3, '시 구조 분석 지문의 기본 어휘로 자주 출제') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('9f9dcfd5-f263-4e5a-96bb-7744b5aa1789', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'conceit', '기발한 비유, 정교한 은유적 착상', '{metaphor,trope}', '{literalism,plainness}', 'The metaphysical poet''s conceit compares two lovers to a compass''s fixed and moving legs.', 'Critics found the novel''s central conceit—a talking house—both whimsical and profound.', 101, '2026-09-16 06:44:32.67489+00', 4, '형이상학파 시나 은유 분석 지문에서 핵심 문학 용어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('ab3da007-d08b-4992-8ea5-b258639ad1d2', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'raconteur', '이야기를 잘하는 사람, 화술가', '{storyteller,narrator}', '{listener,audience}', 'The narrator styles himself as a raconteur, weaving digressions into his central tale.', 'As a skilled raconteur, the grandfather transformed ordinary events into captivating stories.', 102, '2026-09-16 06:44:32.67489+00', 4, '화자의 서술 스타일을 규정하는 문학 지문에서 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('810b3a8f-3a77-4323-ac8c-ca52973215a9', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'bildungsroman', '성장 소설, 주인공의 정신적 성장을 다룬 소설 장르', '{"coming-of-age novel","growth narrative"}', '{"static narrative","unchanging tale"}', 'The novel is often studied as a classic bildungsroman tracing the protagonist''s moral awakening.', 'Critics compared the memoir''s structure to that of a bildungsroman, charting the author''s coming of age.', 103, '2026-09-16 06:44:32.67489+00', 4, '장르 분류 및 서사 구조를 다루는 문학 지문의 전문 용어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('1de8ffd7-3702-4e71-a461-2faebe0ed3c6', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'leitmotif', '반복되는 주제, 라이트모티프', '{"recurring theme",motif}', '{"one-off image","isolated detail"}', 'The image of a caged bird serves as a leitmotif throughout the collection of poems.', 'Critics traced the leitmotif of exile across the author''s entire body of work.', 104, '2026-09-16 06:44:32.67489+00', 4, '주제 반복 및 상징 분석 지문에서 자주 등장하는 전문어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('a7f5033d-f98a-4fc6-ae2c-7579402b88fc', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'apocryphal', '출처가 불분명하거나 진위가 의심스러운(이야기)', '{dubious,unverified}', '{authenticated,verified}', 'The biography includes several apocryphal stories about the poet''s youth that scholars now dispute.', 'Critics note that the anecdote about the author''s deathbed confession is likely apocryphal.', 105, '2026-09-16 06:44:32.67489+00', 4, '전기·역사적 서술의 신빙성 평가 지문에서 자주 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('4933c5db-fa59-46ae-9afb-719d3fc21bbc', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'embellishment', '이야기나 사실을 꾸미거나 과장하는 것', '{exaggeration,ornamentation}', '{understatement,plainness}', 'The narrator''s embellishment of ordinary events lends the memoir a fantastical quality.', 'Scholars question whether the historical account contains embellishment beyond the factual record.', 106, '2026-09-16 06:44:32.67489+00', 3, '서술 기법 및 신뢰성 분석 지문 고빈도') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('193ed11d-b0ac-422d-b28c-0ba3f3da76a5', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'exposit', '체계적으로 설명하다, 상술하다', '{explain,elucidate}', '{obscure,confound}', 'The critic uses the opening chapter to exposit the novel''s central themes before the plot unfolds.', 'In her essay, she exposits the historical context necessary to understand the poem''s allusions.', 107, '2026-09-16 06:44:32.67489+00', 4, '수사학적 분석 지문에서 설명 구조 파악에 필요한 동사') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('c8717139-5d18-4c7f-8464-c02d57535456', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'ephemeral', '덧없는, 순간적인', '{fleeting,transient}', '{enduring,permanent}', 'The poem laments the ephemeral nature of youth and beauty.', 'Critics argue that the novel''s satirical references, once biting, now feel ephemeral to modern readers.', 108, '2026-09-16 06:44:32.67489+00', 3, '서정시 및 주제 분석 지문에서 시간성 논의에 자주 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('64a1a882-bf7e-4119-9935-32f4f087ab09', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'verbiage', '불필요하게 장황한 말, 수식이 많은 표현', '{wordiness,prolixity}', '{conciseness,succinctness}', 'The editor trimmed the excessive verbiage that obscured the essay''s main argument.', 'Critics fault the novelist''s verbiage, arguing that a simpler style would heighten the story''s impact.', 109, '2026-09-16 06:44:32.67489+00', 3, '문체 비평 지문에서 장황함을 지적할 때 자주 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('33a37d12-9fec-4b59-a91a-d58dada75a9c', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'antithesis', '정반대되는 것, 대조를 이루는 수사법', '{contrast,opposite}', '{similarity,equivalence}', 'The stoic hero serves as the antithesis of the impulsive villain in the play.', 'The poet employs antithesis, pairing images of light and darkness to heighten the tension.', 110, '2026-09-16 06:44:32.67489+00', 4, '수사법 분석 지문에서 대조 기법 설명에 필수적인 용어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('1f2fefc7-94b6-46f3-a5bc-7dd92e93c77d', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'exalt', '높이 찬양하다, 격상시키다', '{glorify,extol}', '{debase,demean}', 'The ode exalts the fallen soldier as a symbol of national sacrifice.', 'Throughout the novel, the narrator exalts simplicity over material wealth.', 111, '2026-09-16 06:44:32.67489+00', 3, '찬가·엘레지 지문에서 인물 미화 표현 분석에 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('9811209e-4da5-481e-aeba-9f7103e7ae56', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'disjointed', '뒤죽박죽인, 연결이 매끄럽지 않은', '{fragmented,incoherent}', '{cohesive,seamless}', 'The novel''s disjointed timeline forces readers to piece together the plot themselves.', 'Some reviewers found the memoir''s disjointed structure disorienting rather than innovative.', 112, '2026-09-16 06:44:32.67489+00', 3, '서사 구조 분석 지문에서 비선형적 구성 설명에 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('0ac290e3-2098-4673-9642-daa3033adaf3', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'portentous', '불길한 징조를 나타내는, 거창한', '{ominous,foreboding}', '{trivial,insignificant}', 'The storm''s portentous arrival foreshadows the tragedy to come.', 'Critics mock the film''s portentous dialogue as overwrought and self-important.', 113, '2026-09-16 06:44:32.67489+00', 4, '복선 및 어조 분석 지문에서 불길함 표현에 자주 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('b729e9ff-9698-4fc4-b4cb-33c34c40e660', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'euphonious', '듣기 좋은, 음조가 아름다운', '{melodious,harmonious}', '{cacophonous,discordant}', 'The poet chooses euphonious words to create a soothing musical effect.', 'Critics admire the euphonious rhythm of her verse even when its meaning is obscure.', 114, '2026-09-16 06:44:32.67489+00', 4, '시의 음운적 효과 분석 지문에서 사용되는 전문 어휘') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('aacc2ee9-c246-46dc-a43d-ac0af502c7ee', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'sonorous', '울림이 깊고 낭랑한', '{resonant,booming}', '{muted,toneless}', 'The narrator''s sonorous voice lends gravity to the funeral scene.', 'The poem''s sonorous lines seem designed to be read aloud.', 115, '2026-09-16 06:44:32.67489+00', 4, '낭독 및 음향적 효과 분석 지문에서 자주 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('9268e0c3-8912-4584-9264-248443dcc9fc', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'cryptic', '난해한, 뜻이 모호한', '{enigmatic,obscure}', '{clear,transparent}', 'The novel ends with a cryptic message that invites multiple interpretations.', 'Critics have long debated the meaning of the poet''s cryptic final stanza.', 116, '2026-09-16 06:44:32.67489+00', 3, '결말의 모호성 및 해석 분석 지문에서 빈번히 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('a2ac05a3-f2b9-4e29-8598-c24379514dce', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'alliteration', '두운법(첫소리 자음 반복)', '{consonance,repetition}', '{dissonance,irregularity}', 'The poet''s use of alliteration in ''wild and windy night'' creates a musical, driving rhythm.', 'Critics noted that the columnist''s fondness for alliteration sometimes made her prose feel gimmicky.', 117, '2026-09-16 06:44:32.67489+00', 3, '시 분석 지문에서 음운적 장치를 설명할 때 자주 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('42dd7667-63c6-4b5a-bf8d-eaba2093a388', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'genre', '장르, 작품의 갈래', '{category,type}', '{singularity,uniqueness}', 'The novel defies easy classification, blending elements of the mystery genre with literary fiction.', 'Her early work belongs squarely to the pastoral genre, celebrating rural simplicity.', 118, '2026-09-16 06:44:32.67489+00', 3, '문학 지문에서 작품 분류를 논할 때 필수 어휘') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('a6237b93-ab82-4cc6-82ce-c0fca780d0b5', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'diction', '어휘 선택, 표현 방식', '{phrasing,wording}', '{inarticulateness,vagueness}', 'The author''s formal diction lends the essay an air of scholarly authority.', 'The playwright''s colloquial diction makes the dialogue feel authentic and immediate.', 119, '2026-09-16 06:44:32.67489+00', 3, '수사학적 분석 지문에서 문체 요소를 설명할 때 고빈도') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('c25dcf83-54df-466a-b371-f4ec5745ed58', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'syntax', '문장 구조, 통사법', '{"sentence structure",construction}', '{incoherence,randomness}', 'The fragmented syntax of the closing paragraph mirrors the narrator''s fractured state of mind.', 'By inverting normal syntax, the poet forces readers to slow down and reconsider each phrase.', 120, '2026-09-16 06:44:32.67489+00', 3, '문체·수사 분석 지문에서 문장 구조를 논할 때 필수어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('aa1af8ab-4b00-43fd-8186-e411b99a9531', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'understatement', '절제된 표현, 축소해서 말하기', '{litotes,minimization}', '{hyperbole,exaggeration}', 'Calling the catastrophe ''a bit of trouble'' is a classic example of British understatement.', 'The narrator''s understatement of his own suffering makes the passage all the more affecting.', 121, '2026-09-16 06:44:32.67489+00', 3, '수사적 효과를 다루는 지문에서 과장법과 대비되어 출제') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('4be16fda-0c42-489d-a4f5-b07c89daa63a', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'colloquial', '구어체의, 일상 회화적인', '{informal,vernacular}', '{formal,literary}', 'The author''s colloquial style makes the dense subject matter more accessible to general readers.', 'Dialogue written in colloquial speech gives the characters a lifelike quality.', 122, '2026-09-16 06:44:32.67489+00', 3, '문체 분석 지문에서 격식 수준을 논할 때 필수어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('608c68f8-5ae7-429b-a248-9cc61a4bfe90', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'eloquence', '웅변, 유창하고 설득력 있는 언변', '{fluency,articulateness}', '{inarticulateness,clumsiness}', 'The eulogy was remembered for its eloquence rather than its length.', 'Her eloquence in debate won over even skeptical audience members.', 123, '2026-09-16 06:44:32.67489+00', 3, '연설문·수사 분석 지문에서 화자의 언변을 평가할 때 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('0360fc61-4221-48ca-b896-694d051fb66c', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'vitality', '생동감, 활력', '{energy,vigor}', '{lethargy,torpor}', 'Despite its somber theme, the poem is charged with vitality and rhythmic energy.', 'Critics credited the novel''s vitality to its unpredictable, larger-than-life protagonist.', 124, '2026-09-16 06:44:32.67489+00', 3, '문체의 생기와 활력을 평가하는 문학 비평 지문에서 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('bc4bc53c-83e4-41ca-b753-3f37cbe351b5', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'incisive', '예리한, 통찰력 있는', '{trenchant,penetrating}', '{superficial,obtuse}', 'The critic''s incisive analysis exposed weaknesses that other reviewers had overlooked.', 'Her incisive wit made her essays both entertaining and intellectually sharp.', 125, '2026-09-16 06:44:32.67489+00', 4, '비평문 지문에서 분석의 날카로움을 표현할 때 고빈도') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('c0bdaff5-777a-40be-8480-f68c292f7269', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'florid', '화려한, 지나치게 장식적인(문체)', '{ornate,flowery}', '{austere,plain}', 'The reviewer criticized the novelist''s florid prose as overwrought and self-indulgent.', 'His florid descriptions of the landscape slowed the narrative''s pace considerably.', 126, '2026-09-16 06:44:32.67489+00', 4, '문체 비평 지문에서 과도한 수식을 지적할 때 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('3ab02aaf-2c8e-469a-99ae-c836bdd76c81', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'cerebral', '지적인, 이성적 사고를 강조하는', '{intellectual,cognitive}', '{visceral,emotional}', 'The novel''s cerebral approach to grief appeals more to the mind than to the heart.', 'Critics found the film''s cerebral plot rewarding but emotionally distant.', 127, '2026-09-16 06:44:32.67489+00', 4, '작품의 지적 성격을 논하는 비평 지문에서 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('8bc3a566-14a0-4b21-acb1-2b167aa3454b', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'visceral', '본능적인, 직관적으로 강렬한(감정적)', '{instinctive,gut-level}', '{cerebral,detached}', 'The battle scene produces a visceral reaction that no amount of analysis can dull.', 'Her visceral description of hunger makes the reader physically uncomfortable.', 128, '2026-09-16 06:44:32.67489+00', 4, '감정적 효과를 다루는 문학 분석 지문에서 cerebral과 대비되어 출제') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('a3e397f2-69cb-4cf6-9bf8-f5e66c7ec8dd', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'catharsis', '정화, 감정의 해소', '{purgation,release}', '{repression,suppression}', 'The tragedy''s final act offers the audience a powerful catharsis, releasing pent-up grief and fear.', 'Writing the memoir served as a form of catharsis for the author after years of silence.', 129, '2026-09-16 06:44:32.67489+00', 4, '문학 비평 지문에서 감정 반응을 설명할 때 자주 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('589d04ea-e40c-470f-a95d-8f6b1fb3a973', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'pundit', '전문가로 자처하는 평론가, 논객', '{commentator,critic}', '{novice,layperson}', 'A literary pundit dismissed the novel as derivative without engaging its subtler themes.', 'The satirical essay mocks television pundits who speak with unearned authority.', 130, '2026-09-16 06:44:32.67489+00', 3, '수사학적 분석 지문에서 화자의 권위를 논할 때 자주 등장') ON CONFLICT (book_id, word) DO NOTHING;
