INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('5850bbca-e052-43b1-b631-19600166fe63', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'exegesis', '(본문에 대한) 해석, 주석', '{interpretation,explication}', '{obfuscation,misreading}', 'The scholar''s exegesis of the poem uncovered layers of religious symbolism.', 'Her exegesis challenged earlier readings that ignored the narrator''s irony.', 133, '2026-09-16 06:44:32.67489+00', 4, '문학 비평 및 텍스트 해석 지문의 전문 어휘로 출제') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('688af292-a16a-4c23-8940-23f3af4badb5', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'mimesis', '모방, (현실의) 재현', '{imitation,representation}', '{invention,abstraction}', 'Aristotle considered mimesis the foundation of dramatic art.', 'The novel''s mimesis of everyday speech gives it a striking authenticity.', 134, '2026-09-16 06:44:32.67489+00', 4, '고전 문학 이론을 다루는 지문에서 자주 언급되는 개념어') ON CONFLICT (book_id, word) DO NOTHING;
