INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('af9c649f-df62-44c7-b9f0-a35e99db9587', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'despair', '절망', '{hopelessness,desolation}', '{hope,optimism}', 'The elegy captures the speaker''s despair at the irrevocable loss of youth.', 'A tone of despair pervades the final chapters of the novel.', 139, '2026-09-16 06:44:32.67489+00', 3, '비가·서정시 분석 지문에서 정서 표현 어휘로 고빈도') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('9c0fd943-94ec-4f39-9a3a-a6c059eea944', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'stilted', '부자연스러운, 딱딱한(문체)', '{awkward,artificial}', '{natural,fluent}', 'The dialogue feels stilted, as if the characters were reciting speeches rather than talking.', 'Early drafts of the play suffered from stilted, overly formal language.', 140, '2026-09-16 06:44:32.67489+00', 4, '문체 비평 지문에서 부자연스러운 표현을 지적할 때 자주 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('373bf971-0038-49d8-a55a-82abc156aea5', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'redemptive', '구원적인, 속죄의 성격을 지닌', '{restorative,salvific}', '{damning,condemnatory}', 'The novel''s redemptive ending suggests that forgiveness can heal generational wounds.', 'Critics debated whether the protagonist''s sacrifice was truly redemptive.', 141, '2026-09-16 06:44:32.67489+00', 4, '서사 구조 및 결말 분석 지문에서 주제 해석에 자주 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('6ecc6691-385c-46af-b747-dde42abc722d', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'omniscient', '전지적인(서술 시점)', '{all-knowing,all-seeing}', '{limited,partial}', 'The omniscient narrator moves freely between the minds of every character.', 'Shifting from an omniscient to a limited perspective alters the reader''s sympathy.', 142, '2026-09-16 06:44:32.67489+00', 3, '서술 시점(narrative perspective)을 다루는 지문의 필수 용어') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('bb54f6fa-ab1e-46ea-bad3-73a8851fe793', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'idyllic', '목가적인, 평화롭고 이상적인', '{pastoral,serene}', '{chaotic,turbulent}', 'The pastoral poem paints an idyllic image of rural life, untouched by modern strife.', 'Beneath its idyllic surface, the village hides long-standing tensions.', 143, '2026-09-16 06:44:32.67489+00', 3, '목가적(pastoral) 문학 장르 분석 지문에서 고빈도 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('22a38d16-543e-4b9d-a123-19fc3fab08be', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'vernacularism', '특정 지역·시대의 일상어 표현', '{colloquialism,idiom}', '{formality,eloquence}', 'The novelist peppered her dialogue with regional vernacularisms to lend authenticity to her rural characters.', 'Critics praised the playwright''s use of vernacularism to capture the rhythms of working-class speech.', 144, '2026-09-16 06:44:32.67489+00', 4, '문학 지문에서 방언·구어체 묘사 분석 시 자주 등장하는 어휘') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('ddec3270-15df-4081-b7ec-38bd11d8b639', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'elegist', '애가(哀歌)를 쓰는 시인', '{mourner-poet,lamenter}', '{celebrant,panegyrist}', 'As an elegist, the poet dedicated much of his career to mourning the losses of war.', 'The anthology collected verses from several elegists who wrote in response to the plague.', 145, '2026-09-16 06:44:32.67489+00', 3, '시 장르 분석 지문에서 애가 형식과 관련해 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('fc9aa229-e80e-4500-b6b0-c4b82653c381', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'raillery', '가벼운 조롱이나 농담', '{banter,teasing}', '{solemnity,gravity}', 'The dialogue was full of raillery, as the two characters traded witty barbs without malice.', 'Her gentle raillery lightened the tense mood of the dinner scene.', 146, '2026-09-16 06:44:32.67489+00', 4, '풍자·희극적 대사 분석 지문에서 자주 쓰이는 수사 어휘') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('a18b3937-d73b-42eb-aae7-d6e0289c80bf', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'obsequy', '장례 의식, 애도 절차', '{"funeral rite","burial ceremony"}', '{celebration,festivity}', 'The novel''s closing chapter describes the somber obsequies held for the fallen soldier.', 'Villagers gathered to perform the traditional obsequies before the burial.', 147, '2026-09-16 06:44:32.67489+00', 4, '서사문학에서 죽음·의례 장면 묘사 시 빈출') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('122c0786-385b-44ae-b07d-7f3330f7f6d9', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'encomium', '찬사, 칭송하는 글이나 연설', '{tribute,eulogy}', '{invective,denunciation}', 'The biographer''s encomium praised the statesman''s unwavering integrity throughout his career.', 'Critics dismissed the review as mere encomium rather than substantive analysis.', 148, '2026-09-16 06:44:32.67489+00', 4, '수사학적 분석 지문에서 찬양문 형식을 다룰 때 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('640b167e-d547-4372-9f09-97e317e35702', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'cacophony', '귀에 거슬리는 불협화음', '{dissonance,discord}', '{euphony,harmony}', 'The poem''s cacophony of harsh consonants mirrors the chaos of the battlefield.', 'Amid the cacophony of the marketplace, the narrator struggled to hear her own thoughts.', 149, '2026-09-16 06:44:32.67489+00', 3, '시적 음향 효과 분석 지문에서 euphony와 대비되어 자주 출제') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('33ad4d7a-a570-4ca9-b362-56d17f5f3f96', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'bathetic', '지나치게 감상적이어서 우스꽝스러운', '{mawkish,maudlin}', '{restrained,understated}', 'The film''s bathetic ending undermined the tragedy it had built for two hours.', 'Reviewers criticized the bathetic dialogue that turned a serious moment into melodrama.', 150, '2026-09-16 06:44:32.67489+00', 4, '감정 과잉 표현 분석 지문에서 bathos의 형용사형으로 출제') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('76dc7844-b6d0-4a12-b311-29194af62ed8', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'epigrammatic', '경구적인, 간결하고 재치 있는', '{terse,pithy}', '{verbose,prolix}', 'Her epigrammatic wit made every line of dialogue quotable.', 'The essayist''s epigrammatic style condensed complex ideas into a single memorable sentence.', 151, '2026-09-16 06:44:32.67489+00', 4, '문체 분석 지문에서 간결한 문장 스타일을 묘사할 때 사용') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('ff2e50bf-3af6-48d1-894d-6cdf8a994587', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'diaphanous', '속이 비칠 정도로 얇은, 은은한(비유적으로 모호한)', '{gauzy,sheer}', '{opaque,dense}', 'The narrator''s diaphanous prose left readers uncertain about what had truly happened.', 'Through the diaphanous veil of metaphor, the poem hinted at unspoken grief.', 152, '2026-09-16 06:44:32.67489+00', 4, '비유적 문체 묘사에서 은유의 투명성을 나타낼 때 등장') ON CONFLICT (book_id, word) DO NOTHING;
INSERT INTO vocab_library_words (id, book_id, word, definition_ko, synonym_words, antonym_words, example1, example2, "position", created_at, difficulty, source_note) VALUES ('e60e6ebd-ec05-481c-8109-c86e8b4eced4', 'c412900b-a28c-43d4-b5fa-d08423e56cc5', 'peroration', '연설의 결론부, 웅변적 마무리', '{"closing speech",summation}', '{exordium,introduction}', 'The senator''s peroration stirred the crowd into applause with its rousing final appeal.', 'In the novel''s closing peroration, the protagonist addresses the reader directly.', 153, '2026-09-16 06:44:32.67489+00', 4, '수사학적 연설 구조 분석 지문에서 결론부를 지칭할 때 사용') ON CONFLICT (book_id, word) DO NOTHING;
